import { Component } from '@angular/core';
import { Sort } from '@angular/material/sort';
import { MatTableDataSource } from '@angular/material/table';
import { Router } from '@angular/router';
import {
  DataService,
  SidebarService,
  apiResultFormat,
  pageSelection,
} from 'src/app/core/core.index';
import { routes } from 'src/app/core/helpers/routes';
import { warehouse } from 'src/app/shared/model/page.model';
import { PaginationService } from 'src/app/shared/shared.index';
import Swal from 'sweetalert2';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';

declare var bootstrap: any;

interface data {
  value: string;
}

@Component({
  selector: 'app-warehouse',
  templateUrl: './warehouse.component.html',
  styleUrl: './warehouse.component.scss',
})
export class WarehouseComponent {
  initChecked = false;
  public routes = routes;
  // pagination variables
  public tableData: Array<warehouse> = [];
  public pageSize = 10;
  public serialNumberArray: Array<number> = [];
  public totalData = 0;
  showFilter = false;
  dataSource!: MatTableDataSource<warehouse>;
  public searchDataValue = '';
  //** / pagination variables
  warehouseForm: FormGroup;
  editWarehouseForm: FormGroup;
  editWarehouseId!: number;
  pagination: any;

  constructor(
    private data: DataService,
    private paginationService: PaginationService,
    private router: Router,
    private sidebar: SidebarService,
    private fb: FormBuilder
  ) {
    this.getTableData();
    this.warehouseForm = this.fb.group({
      warehouse_name: ['', Validators.required],
      address_line_1: ['', Validators.required],
      address_line_2: [''],
      city: ['', Validators.required],
      state: ['', Validators.required],
      country: ['India'],
      pin_code: ['', [Validators.required]],
      phone_number: ['', [Validators.required]],
      country_code: ['', [Validators.required]],
      email: ['', [Validators.required, Validators.email]],
    });
    this.editWarehouseForm = this.fb.group({
      warehouse_name: ['', Validators.required],
      address_line_1: ['', Validators.required],
      address_line_2: [''],
      city: ['', Validators.required],
      state: ['', Validators.required],
      country: ['India'],
      pin_code: ['', [Validators.required]],
      phone_number: ['', [Validators.required]],
      country_code: ['', [Validators.required]],
      email: ['', [Validators.required, Validators.email]],
      is_active: [true, [Validators.required]],
      accepting_donations: [true, [Validators.required]],
    });
  }

  private getTableData(page?:any): void {
    this.data.getWareHouse(page).subscribe((apiRes: any) => {
      this.tableData = [];
      apiRes.results.forEach((res: warehouse, index: number) => {
        // Push data to the table array
        this.tableData.push({
          ...res,
        });
      });
      
      this.paginationService.setPaginationData(apiRes.results.pagination);
      this.pagination = this.paginationService.getPaginationData();
    });
  }
  onPageChange(page: number) {
    this.getTableData(page);
  }
  public editeWarehouse(data: any): void {
    this.editWarehouseId = data.warehouse_id;
    this.editWarehouseForm.patchValue({
      warehouse_name: data.warehouse_name,
      address_line_1: data.address_line_1,
      address_line_2: data.address_line_2,
      city: data.city,
      state: data.state,
      country: data.country,
      pin_code: data.pin_code,
      phone_number: data.phone_number,
      country_code: data.country_code,
      email: data.email,
      is_active: data.is_active,
      accepting_donations: data.accepting_donations,
    });
  }

  public onSubmit(): void {
    if (this.warehouseForm.valid) {
      this.data.createWareHouse(this.warehouseForm.value).subscribe(
        (response) => {
          this.getTableData();
          // Reset form after submission
          this.warehouseForm.reset();
          // Close the modal using Bootstrap's API
          const modalElement = document.getElementById('add-units');
          if (modalElement) {
            const modal = bootstrap.Modal.getInstance(modalElement);
            modal.hide();
          }
        },
        (error) => {
          console.error('Error creating user', error);
        }
      );
    }
  }

  public onUpdate(): void {
    if (this.editWarehouseForm.valid) {
      const formData = { ...this.editWarehouseForm.value };
      this.data.updateWareHouse(this.editWarehouseId, formData).subscribe(
        (response) => {
          console.log('Announcement updated successfully', response);
          this.getTableData();
          const modalElement = document.getElementById('edit-units');
          if (modalElement) {
            const modal = bootstrap.Modal.getInstance(modalElement);
            modal.hide();
          }
          // this.resetEditForm();
        },
        (error) => {
          console.error('Error updating announcement', error);
        }
      );
    }
  }
  public sortData(sort: Sort) {
    const data = this.tableData.slice();
    if (!sort.active || sort.direction === '') {
      this.tableData = data;
    } else {
      this.tableData = data.sort((a, b) => {
        const aValue = (a as never)[sort.active];
        const bValue = (b as never)[sort.active];
        return (aValue < bValue ? -1 : 1) * (sort.direction === 'asc' ? 1 : -1);
      });
    }
  }

  public searchData(value: string): void {
    this.dataSource.filter = value.trim().toLowerCase();
    this.tableData = this.dataSource.filteredData;
  }

  confirmColor() {
    const swalWithBootstrapButtons = Swal.mixin({
      customClass: {
        confirmButton: ' btn btn-success',
        cancelButton: 'me-2 btn btn-danger',
      },
      buttonsStyling: false,
    });

    swalWithBootstrapButtons
      .fire({
        title: 'Are you sure?',
        text: "You won't be able to revert this!",
        confirmButtonText: 'Yes, delete it!',
        showCancelButton: true,
        cancelButtonText: 'Cancel',
        reverseButtons: true,
      })
      .then((result) => {
        if (result.isConfirmed) {
          swalWithBootstrapButtons.fire(
            'Deleted!',
            'Your file has been deleted.',
            'success'
          );
        } else if (result.dismiss === Swal.DismissReason.cancel) {
          swalWithBootstrapButtons.fire(
            'Cancelled',
            'Your imaginary file is safe :)',
            'error'
          );
        }
      });
  }

  public selectedValue1 = '';
  public selectedValue2 = '';
  public selectedValue3 = '';
  public selectedValue4 = '';
  public selectedValue5 = '';
  public selectedValue6 = '';
  public selectedValue7 = '';
  public selectedValue8 = '';
  public selectedValue9 = '';

  selectedList1: data[] = [
    { value: 'Sort by Date' },
    { value: 'Newest' },
    { value: 'Oldest' },
  ];
  selectedList2: data[] = [
    { value: 'Choose Warehouse' },
    { value: 'Legendary' },
    { value: 'Determined' },
    { value: 'Sincere' },
    { value: 'Pretty' },
  ];
  selectedList3: data[] = [
    { value: 'Choose Person' },
    { value: 'Steven' },
    { value: 'Gravely' },
  ];
  selectedList4: data[] = [
    { value: 'Choose Status' },
    { value: 'Active' },
    { value: 'Inactive' },
  ];
  selectedList5: data[] = [
    { value: 'Choose Status' },
    { value: 'Active' },
    { value: 'Inactive' },
  ];
  selectedList6: data[] = [
    { value: 'Choose' },
    { value: 'Steven' },
    { value: 'Gravely' },
  ];
  selectedList7: data[] = [
    { value: 'Choose' },
    { value: 'United Kingdom' },
    { value: 'United State' },
  ];
  selectedList8: data[] = [
    { value: 'Choose' },
    { value: 'Steven' },
    { value: 'Gravely' },
  ];
  selectedList9: data[] = [
    { value: 'United Kingdom' },
    { value: 'United State' },
  ];

  public filter = false;
  openFilter() {
    this.filter = !this.filter;
  }
  isCollapsed: boolean = false;
  toggleCollapse() {
    this.sidebar.toggleCollapse();
    this.isCollapsed = !this.isCollapsed;
  }
  showBox = false;

  toggleBox() {
    this.showBox = !this.showBox;
  }
  selectAll(initChecked: boolean) {
    if (!initChecked) {
      this.tableData.forEach((f) => {
        f.isSelected = true;
      });
    } else {
      this.tableData.forEach((f) => {
        f.isSelected = false;
      });
    }
  }
}
